import React from 'react';
import { useApp } from '../context/AppContext';
import { acknowledgeAlert } from '../services/api';

const icons = {
  Fire: '🔥', Violence: '⚡', Gun: '🔫',
  Falling: '🏃', Theft_Mask: '🎭', Smoke: '💨',
  Knife: '🔪', Phone: '📱', Normal: '🛡️'
};

const sevStyles = {
  High:   { color: '#f87171', bg: '#450a0a' },
  Medium: { color: '#fbbf24', bg: '#2d220a' },
  Low:    { color: '#4ade80', bg: '#0d2010' }
};

export default function AlertsPanel() {
  const { alerts, refreshAlerts } = useApp();

  const handleAck = async (id) => {
    try {
      await acknowledgeAlert(id);
      await refreshAlerts();
    } catch (err) {
      console.error('Acknowledge failed:', err);
    }
  };

  const active = alerts.filter(a => !a.acknowledged).slice(0, 5);

  return (
    <div style={{ borderBottom: '1px solid #1e2d47', padding: '10px 12px', flexShrink: 0 }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 8 }}>
        <span style={{ fontSize: 11, fontWeight: 700, color: '#94a3b8', textTransform: 'uppercase', letterSpacing: '.5px' }}>
          Recent Alerts
        </span>
        <span style={{ fontSize: 10, color: '#3b82f6', cursor: 'pointer' }}>View All</span>
      </div>

      {active.length === 0 && (
        <div style={{ fontSize: 11, color: '#64748b', textAlign: 'center', padding: '12px 0' }}>
          ✅ No active alerts
        </div>
      )}

      {active.map((a, i) => {
        const sev = sevStyles[a.severity] || sevStyles.Low;
        return (
          <div
            key={a.id}
            onClick={() => handleAck(a.id)}
            title="Click to acknowledge"
            style={{
              display: 'flex', alignItems: 'center', gap: 8,
              padding: '5px 0', cursor: 'pointer',
              borderBottom: i < active.length - 1 ? '1px solid #1e2d47' : 'none'
            }}
          >
            <span style={{ fontSize: 18, width: 26, textAlign: 'center', flexShrink: 0 }}>
              {icons[a.type] || '⚠️'}
            </span>
            <div style={{ flex: 1, minWidth: 0 }}>
              <div style={{ fontSize: 11, fontWeight: 600, color: '#fff' }}>{a.type} Detected</div>
              <div style={{ fontSize: 10, color: '#64748b', marginTop: 1 }}>{a.camera_name}</div>
            </div>
            <div style={{ textAlign: 'right', flexShrink: 0 }}>
              <div style={{ fontSize: 10, color: '#64748b' }}>{a.timestamp}</div>
              <span style={{ fontSize: 9, fontWeight: 700, padding: '2px 6px', borderRadius: 3, background: sev.bg, color: sev.color, display: 'inline-block', marginTop: 2 }}>
                {a.severity}
              </span>
            </div>
          </div>
        );
      })}
    </div>
  );
}
